-- The pack's vendored Step 3 arbiter must answer what the pin answers (card t_9b305cc8).
--
-- WHY THIS FIXTURE EXISTS. `MightiePack/Modules/Touchstone/ChestAdvisor/` now ships
-- two modules that decide the Step 3 verdict — `StatOrders.lua` (the published stat
-- orders, as data) and `Arbitration.lua` (the healer model: `Arbitration.judge`
-- returns UPGRADE / NOT_UPGRADE / SIDEGRADE, or refuses). Both are generated by
-- `tools/sync_touchstone.py` from the pinned StatForge commit and neither carries a
-- pack patch, so the pack believes it ships the upstream arbiter unmodified. Until
-- this file existed, nothing checked that belief against a verdict: a re-sync that
-- moved the pin, or a patch that quietly landed on one of the two files, would have
-- changed Step 3 answers with every other spec still green — because every other
-- spec compares the pack with itself.
--
-- THE TWO SIDES, AND WHAT PROVES EACH ONE.
--
--   (a) StatForge @ pin 1992240 — the upstream reference. The pin is a private
--       repository, so CI cannot check it out. What CI *can* do is load the two
--       shipped files with no pack code and no host table at all, which is how
--       upstream loads them (`Arbitration.lua` and `StatOrders.lua` are standalone
--       by their own headers). The identity "the bytes loaded here are the pin's
--       bytes" is not assumed: the COPY lane of `tools/sync_touchstone.py` puts them
--       there unpatched, leg 0 below asserts no patch file exists for either, and
--       `--verify-shipped` hashes both against `tools/touchstone-patches/pin.txt` in
--       the same CI job. The behaviour identity is this fixture's job, and it is
--       pinned against answers measured from a real checkout (see PROVENANCE).
--
--   (b) MightiePack as wired — the pack's own load order (Constants, Weights,
--       Verdict, StatOrders, Arbitration — `MightiePack.toc` lines 18-29, Verdict
--       BEFORE StatOrders BEFORE Arbitration, which is NOT the pin's order), the
--       pack's patched `Verdict.lua` as the caller, and the answers asked through
--       the pack's own surfaces: `Verdict.arbitrate` (the seam) and
--       `StatForge.StatOrders` (the host table). This is the copy a player's client
--       runs.
--
-- The four Step 3 states are each named below: upgrade, not-an-upgrade, sidegrade
-- and refusal. Character and context are held constant (the §5a measured healer,
-- raid) so the state is a function of the chest pair alone; the refusal case carries
-- two refusals because the ladder refuses for two different reasons — data that
-- never arrived, and a stat the model cannot price.
--
-- PROVENANCE OF THE RECORDED COLUMN. Every `recorded` field below was measured, not
-- remembered: the pin's `Constants.lua`, `Weights.lua`, `StatOrders.lua`,
-- `Verdict.lua` and `Arbitration.lua` were loaded in the pin's own TOC order
-- (StatOrders before Verdict), then asked the same five inputs through
-- `Verdict.arbitrate` and `Arbitration.judge`. The two refusals print
-- `Arbitration.why`, because a refusal's answer IS its reason.
--
-- CARD t_18eb91e6 RE-MEASURED THE COLUMN AT 1992240. A8 (the refusal clause) moved
-- what a refusal hands UP, not what the model decides: the three judged cases
-- answer byte-identically to the previous column (the margins and bands below are
-- the eebfba4 numbers, re-measured and unchanged), while a refusal now carries a
-- stable CAUSE KEY beside its sentence (`secret_totals` here; the crit case's key,
-- `moves_unpriced`, is deliberately one the pack's clause map does not name, so the
-- renderer falls back to its plain clause). The recorded `cause` fields are the
-- keys measured at 1992240, and section 5 asserts the shipped seam hands each one
-- out with `declined = true`.
--
-- That run was itself cross-checked against the pin's own battery before the numbers
-- were written down here: replaying the battery's `owner-mid-raid` and
-- `owner-low-dungeon` inputs through the same load reproduced their hand-computed
-- figures to six decimals (margin -0.000908 / -0.035149, band 0.007132 / 0.059477 —
-- ChestAdvisor/tests/step3_cases.lua), which is how we know the reference run is the
-- model the pin's battery asserts rather than a lookalike. Neither of those pairs is
-- one of the five inputs below: the sidegrade input was chosen for the FLOOR instead
-- (see case 3), so that a pin which changed either decision constant moves this
-- fixture.
--
-- A DIVERGENCE FAILS LOUDLY: each input prints side (a) and side (b) verbatim, then
-- the fixture diffs them field by field and names both values. Two further legs run
-- on every execute: the recorded column must still match (a) — so a re-sync that
-- moves an answer is caught by name — and the pack's order must match the pin's
-- order when the same bytes are loaded in it (the parent card's TOC reorder is
-- inert, proven rather than assumed).
--
-- Run from the repo root:  lua5.1 tests/touchstone_arbitration_parity_spec.lua

local here = (arg and arg[0] or "tests/touchstone_arbitration_parity_spec.lua"):match("^(.*)[/\\][^/\\]*$") or "."
local root = here:gsub("[/\\]tests$", "")
if root == "tests" then root = "." end
local TOUCH = root .. "/MightiePack/Modules/Touchstone/"
local PATCHES = root .. "/tools/touchstone-patches/"

local failed = 0
local checks = 0
local function check(cond, msg)
  checks = checks + 1
  if not cond then
    failed = failed + 1
    io.stderr:write("FAIL: " .. tostring(msg) .. "\n")
  end
  return cond and true or false
end

local function fileExists(path)
  local f = io.open(path, "r")
  if f then f:close() return true end
  return false
end

local function readAll(path)
  local f = io.open(path, "rb")
  if not f then return nil end
  local s = f:read("*a")
  f:close()
  return s
end

-- A missing vendored tree is a different failure from a diverging verdict: say so and
-- stop, rather than let a nil module raise a traceback three sections later.
for _, name in ipairs({ "ChestAdvisor/StatOrders.lua", "ChestAdvisor/Arbitration.lua",
                        "ChestAdvisor/Verdict.lua", "Constants.lua", "Weights.lua" }) do
  if not fileExists(TOUCH .. name) then
    io.stderr:write("FAIL: the vendored Touchstone is incomplete — missing " .. name .. "\n")
    os.exit(1)
  end
end

-- ═══════════════════════════════════════════════════════════════════════════════
-- 0. These bytes are the pin's bytes
-- ═══════════════════════════════════════════════════════════════════════════════
-- The parity claim is worthless if the file under test is not the file the pin
-- ships. Two cheap structural facts stand in for the hash: a COPY-lane file has no
-- patch (a patched file is by definition not the pin's blob), and the pin manifest
-- names it. The hash itself is `--verify-shipped`, which CI runs on every PR.

local VENDORED = { "Arbitration.lua", "StatOrders.lua" }
local manifest = readAll(PATCHES .. "pin.txt")
check(manifest ~= nil, "tools/touchstone-patches/pin.txt is readable (the pin manifest)")

local function manifestHash(relpath)
  if not manifest then return nil end
  for line in manifest:gmatch("[^\r\n]+") do
    local hash, path = line:match("^(%x+)%s+(.+)$")
    if path == relpath then return hash end
  end
  return nil
end

for _, name in ipairs(VENDORED) do
  -- The patch lane names a nested file `ChestAdvisor__<file>.lua.patch`; the
  -- absence of that file is what makes this a copy rather than a patched copy.
  check(not fileExists(PATCHES .. "ChestAdvisor__" .. name .. ".patch"),
    name .. " has no pack patch — the COPY lane ships the pin's blob (a patch would make it not-the-pin)")
  local hash = manifestHash("ChestAdvisor/" .. name)
  check(type(hash) == "string" and #hash == 64,
    ("the pin manifest names ChestAdvisor/%s with a sha256 (got %s)"):format(name, tostring(hash)))
  check(fileExists(TOUCH .. "ChestAdvisor/" .. name),
    "MightiePack ships ChestAdvisor/" .. name)
end

-- The pack's TOC order, read rather than assumed: (b) below loads in this order, so
-- a reordered TOC must fail here rather than silently load something else.
local tocBody = readAll(root .. "/MightiePack/MightiePack.toc")
check(tocBody ~= nil, "MightiePack.toc is readable")
local tocAt = {}
if tocBody then
  local index = 0
  for line in tocBody:gmatch("[^\r\n]+") do
    index = index + 1
    if line:find("ChestAdvisor/Verdict.lua", 1, true) then tocAt.verdict = index end
    if line:find("ChestAdvisor/StatOrders.lua", 1, true) then tocAt.statOrders = index end
    if line:find("ChestAdvisor/Arbitration.lua", 1, true) then tocAt.arbitration = index end
  end
end
check(type(tocAt.verdict) == "number" and type(tocAt.statOrders) == "number"
  and type(tocAt.arbitration) == "number", "the TOC lists Verdict.lua, StatOrders.lua and Arbitration.lua")
check(tocAt.verdict and tocAt.statOrders and tocAt.verdict < tocAt.statOrders,
  "the TOC loads Verdict.lua before StatOrders.lua (the pack's order, not the pin's)")
check(tocAt.statOrders and tocAt.arbitration and tocAt.statOrders < tocAt.arbitration,
  "the TOC loads StatOrders.lua before Arbitration.lua")

-- ═══════════════════════════════════════════════════════════════════════════════
-- 1. Three environments, one process
-- ═══════════════════════════════════════════════════════════════════════════════
-- Each engine gets its own global table (Lua 5.1 `setfenv`), so `_G.Arbitration`,
-- `_G.StatOrders` and `_G.StatForge` in one cannot be seen by another. Standard
-- library functions fall through to the real `_G`; everything the addon itself
-- writes stays inside the sandbox.

local function sandbox()
  local env = {}
  env._G = env
  env.arg = {}
  setmetatable(env, { __index = _G })
  return env
end

local function loadInto(env, path, label)
  local chunk, err = loadfile(path)
  if not check(chunk ~= nil, "loadfile " .. label .. ": " .. tostring(err)) then return false end
  setfenv(chunk, env)
  -- The client passes (addonName, namespace); these files read neither, but a
  -- host-shaped call keeps the load identical to the one Core/module loading does.
  local ok, runErr = pcall(chunk, "MightiePack", { Print = function() end })
  return check(ok, "load " .. label .. ": " .. tostring(runErr))
end

-- (a) the upstream reference: the two modules alone, in the pin's order, with no
-- host core and no Verdict. If either file needed the pack to load, this fails.
local REF = sandbox()
loadInto(REF, TOUCH .. "ChestAdvisor/StatOrders.lua", "reference StatOrders.lua")
loadInto(REF, TOUCH .. "ChestAdvisor/Arbitration.lua", "reference Arbitration.lua")
check(type(REF.StatOrders) == "table" and type(REF.StatOrders.get) == "function",
  "(a) StatOrders.lua loads standalone and publishes StatOrders.get")
check(type(REF.Arbitration) == "table" and type(REF.Arbitration.judge) == "function"
  and type(REF.Arbitration.why) == "function",
  "(a) Arbitration.lua loads standalone and publishes judge + why")
check(REF.StatForge == nil,
  "(a) the reference environment has no host table — this is upstream's load, not the pack's")

-- (b) the pack as wired: the TOC's order for these five files, pack Verdict as the
-- caller, questions asked through Verdict.arbitrate and StatForge.StatOrders.
local PACKED = sandbox()
local PACK_ORDER = {
  { "Constants.lua", "Constants.lua" },
  { "Weights.lua", "Weights.lua" },
  { "ChestAdvisor/Verdict.lua", "ChestAdvisor/Verdict.lua" },
  { "ChestAdvisor/StatOrders.lua", "ChestAdvisor/StatOrders.lua" },
  { "ChestAdvisor/Arbitration.lua", "ChestAdvisor/Arbitration.lua" },
}
for _, entry in ipairs(PACK_ORDER) do
  loadInto(PACKED, TOUCH .. entry[1], "pack " .. entry[2])
end
local PV = PACKED.Verdict
local PA = PACKED.Arbitration
check(type(PV) == "table" and type(PV.arbitrate) == "function",
  "(b) the pack's Verdict.lua loads and publishes Verdict.arbitrate")
check(type(PA) == "table" and type(PA.judge) == "function",
  "(b) the pack's Arbitration.lua is the arbiter Verdict.arbitrate calls")
check(PACKED.StatForge and PACKED.StatForge.StatOrders == PACKED.StatOrders,
  "(b) StatOrders.lua publishes into the pack's host table (StatForge.StatOrders IS StatOrders)")
check(PACKED.StatForge and PACKED.StatForge.Arbitration == PA,
  "(b) Arbitration.lua publishes into the pack's host table (StatForge.Arbitration IS Arbitration)")
check(type(PV.ARBITRATION_STATE_TOKEN) == "table",
  "(b) the pack ships the state -> token map Verdict.arbitrate reads")

-- (c) the same vendored bytes loaded in the PIN's order (StatOrders before Verdict).
-- The parent card moved Verdict to line 27 and StatOrders to 28 on the argument that
-- nothing in the shipped tree reads StatOrders at load. This leg proves the argument
-- instead of trusting it.
local PINORDER = sandbox()
for _, name in ipairs({ "Constants.lua", "Weights.lua", "ChestAdvisor/StatOrders.lua",
                        "ChestAdvisor/Verdict.lua", "ChestAdvisor/Arbitration.lua" }) do
  loadInto(PINORDER, TOUCH .. name, "pin-order " .. name)
end
check(type(PINORDER.Verdict) == "table" and type(PINORDER.Verdict.arbitrate) == "function"
  and type(PINORDER.Arbitration) == "table",
  "(c) the pin's load order gives the same two modules")

-- ═══════════════════════════════════════════════════════════════════════════════
-- 2. The character snapshot and the four cases
-- ═══════════════════════════════════════════════════════════════════════════════
-- ONE character, ONE context, so each state is a property of the chest pair. The
-- numbers are the §5a measured healer the pin's battery uses (`MID`, level 34:
-- 2,060 mana, 5.5885 regen while casting, 6.38% crit, +36 Healing).
local SPELL = { id = 19939, name = "Holy Light", rank = 5, cost = 190, castTimeMs = 2500 }
local MID = {
  pool = 2060, regenCasting = 5.5885, crit = 6.38, bonusHealing = 36, level = 34,
  regenMeasured = true, spell = SPELL,
  stats = { Intellect = 101, Spirit = 80 },
}
local SPEC = { role = "spell", class = "PALADIN", context = "raid" }

local BETTER = { Intellect = 12, Healing = 30 }   -- the new chest
local WORN = { Intellect = 10, Healing = 20 }     -- the one being worn
local TRADE_C = { Intellect = 6, Healing = 38 }   -- trades Intellect for Healing
local TRADE_E = { Intellect = 12, Healing = 15 }
local CRIT_C = { Intellect = 6, Healing = 32, Crit = 10 }

-- Each input carries the answers measured at 1992240 (see PROVENANCE in the header).
-- `state`/`margin`/`band`/`driving`/`binding`/`confidence`/`reason` are
-- `Arbitration.judge`; `token`/`tokenReason` are `Verdict.arbitrate`; `why` is
-- `Arbitration.why`, which is the whole answer when the ladder refuses.
-- The four cases under test carry five inputs between them: the refusal state has
-- two ways in, and a fixture that pinned only one of them would let the other rot.
local CASES = {
  {
    label = "case 1 · Upgrade",
    note = "the new chest strictly improves the worn one on both stats the model prices",
    cand = BETTER, eq = WORN,
    recorded = {
      token = "UPGRADE", state = "UPGRADE",
      margin = 0.022906, band = 0.002796,
      driving = "healing", binding = "mana", confidence = "low",
      reason = "Raid healing: an upgrade — the extra healing per cast outruns the "
        .. "smaller pool, and you would run dry after about 20 casts either way. "
        .. "(confidence low: crit multiplier unmeasured)",
      why = nil,
    },
  },
  {
    label = "case 2 · Not an upgrade",
    note = "the same two chests, the worn one now in the candidate slot: strictly worse",
    cand = WORN, eq = BETTER,
    recorded = {
      token = "NOT_UPGRADE", state = "NOT_UPGRADE",
      margin = -0.022661, band = 0.002750,
      driving = "healing", binding = "mana", confidence = "low",
      reason = "Raid healing: not an upgrade — the mana it costs buys fewer casts than "
        .. "the healing it adds, and you would run dry after about 20 casts. "
        .. "(confidence low: crit multiplier unmeasured)",
      why = nil,
    },
  },
  {
    label = "case 3 · Sidegrade",
    note = "trades Intellect for Healing; the margin clears the band but not the 1% floor, so the FLOOR calls it",
    cand = TRADE_C, eq = TRADE_E,
    recorded = {
      -- The model's word is SIDEGRADE; the token every surface renders is TRADE_OFF.
      -- margin +0.007561 > band +0.007192, and both are under A.FLOOR (0.01): the
      -- band says "wide enough to see", the floor says "still too small to call".
      -- That makes a change to either constant visible here — a pin that NARROWED
      -- the floor under this margin would turn the input into an UPGRADE.
      token = "TRADE_OFF", state = "SIDEGRADE",
      margin = 0.007561, band = 0.007192,
      driving = "healing", binding = "mana", confidence = "low",
      reason = "Raid healing: under the band either way — pick the one you like. "
        .. "(confidence low: crit multiplier unmeasured)",
      why = nil,
    },
  },
  {
    label = "case 4a · Refusal — missing data",
    note = "the same pair the sidegrade judged, refused because the numbers never arrived",
    cand = TRADE_C, eq = TRADE_E,
    totals = { secret = true },
    recorded = {
      token = nil, state = nil, margin = nil, band = nil,
      driving = nil, binding = nil, confidence = nil, reason = nil,
      why = "totals are secret: the client would not hand them over",
      cause = "secret_totals",
    },
  },
  {
    label = "case 4b · Refusal — a stat the model does not price",
    note = "a chest that moves Crit: a stat the healer model does not price",
    cand = CRIT_C, eq = TRADE_E,
    recorded = {
      token = nil, state = nil, margin = nil, band = nil,
      driving = nil, binding = nil, confidence = nil, reason = nil,
      why = "the pair moves Crit, which the healer model does not price",
      -- A key the pack's clause map does not name on purpose: the renderer must fall
      -- back to its plain clause rather than blank the line (see the header).
      cause = "moves_unpriced",
    },
  },
}

local function totalsFor(input)
  local t = {}
  for k, v in pairs(MID) do t[k] = v end
  if input.totals then
    for k, v in pairs(input.totals) do t[k] = v end
  end
  return t
end

-- ═══════════════════════════════════════════════════════════════════════════════
-- 3. One record per side, in the same shape
-- ═══════════════════════════════════════════════════════════════════════════════

local function judgeRecord(A, input)
  local totals = totalsFor(input)
  local v = A.judge(input.cand, input.eq, SPEC, totals)
  local why = A.why(input.cand, input.eq, SPEC, totals)
  return {
    state = v and v.state or nil,
    margin = v and v.margin or nil,
    band = v and v.band or nil,
    driving = v and v.driving or nil,
    binding = v and v.binding or nil,
    confidence = v and v.confidence or nil,
    reason = v and v.reason or nil,
    why = why,
  }
end

local function wiredRecord(V, A, input)
  local totals = totalsFor(input)
  local token, tokenReason, detail = V.arbitrate(input.cand, input.eq, SPEC, totals)
  local why = A.why(input.cand, input.eq, SPEC, totals)
  return {
    token = token,
    tokenReason = tokenReason,
    -- A8: a refusal is disclosed, not dropped — the detail says so and carries the
    -- model's stable cause key. nil on every pair the model actually judged.
    declined = (type(detail) == "table" and detail.declined == true) or nil,
    cause = (type(detail) == "table" and detail.declined == true) and detail.cause or nil,
    state = detail and detail.state or nil,
    margin = detail and detail.margin or nil,
    band = detail and detail.band or nil,
    driving = detail and detail.driving or nil,
    binding = detail and detail.binding or nil,
    confidence = detail and detail.confidence or nil,
    reason = detail and detail.reason or nil,
    why = why,
  }
end

-- ═══════════════════════════════════════════════════════════════════════════════
-- 4. Printing and diffing
-- ═══════════════════════════════════════════════════════════════════════════════

local function q(value)
  if value == nil then return "nil" end
  return '"' .. tostring(value) .. '"'
end

local function num(value)
  if type(value) ~= "number" then return "--" end
  return string.format("%+.6f", value)
end

local function pairOf(stats)
  local entries = {}
  for word, points in pairs(stats) do
    entries[#entries + 1] = { word = word, points = points }
  end
  table.sort(entries, function(a, b) return a.word < b.word end)
  local words = {}
  for i, entry in ipairs(entries) do
    words[i] = string.format("%+d %s", entry.points, entry.word)
  end
  return table.concat(words, ", ")
end

local function printSide(tag, rec, wired)
  print(("  %s  %s"):format(tag, tostring(rec.state)))
  print(("        margin %s   band %s   driving %s   binding %s   confidence %s")
    :format(num(rec.margin), num(rec.band), tostring(rec.driving), tostring(rec.binding),
      tostring(rec.confidence)))
  print(("        reason  %s"):format(q(rec.reason)))
  if wired then
    print(("        token   %s"):format(q(rec.token)))
    if rec.declined then
      print(("        declined %s   cause %s"):format(tostring(rec.declined), q(rec.cause)))
    end
    if rec.token ~= nil and rec.tokenReason ~= rec.reason then
      print(("        token reason, rewritten by the seam  %s"):format(q(rec.tokenReason)))
    end
  end
  if rec.why ~= nil then
    print(("        why     %s"):format(q(rec.why)))
  end
end

-- The judge-level fields both sides have. `token`/`tokenReason` exist only on the
-- wired side; the token is compared separately, against the pack's own map and
-- against the recorded upstream seam (section 5).
local JUDGE_FIELDS = { "state", "margin", "band", "driving", "binding", "confidence", "reason", "why" }

-- Field-by-field comparison. Margins and bands are doubles produced by the same
-- arithmetic in the same interpreter, so equality is exact; the tolerance exists so
-- the message still carries both numbers if a future pin legitimately introduces a
-- difference in the last bits.
local function sameValue(a, b)
  if type(a) == "number" and type(b) == "number" then return math.abs(a - b) <= 1e-9 end
  return a == b
end

local function shown(value)
  if type(value) == "number" then return num(value) end
  return q(value)
end

local function diffJudge(label, a, b)
  local diverged = false
  for _, field in ipairs(JUDGE_FIELDS) do
    if not sameValue(a[field], b[field]) then
      diverged = true
      failed = failed + 1
      io.stderr:write(("FAIL: %s diverge on %s\n    (a) %s\n    (b) %s\n")
        :format(label, field, shown(a[field]), shown(b[field])))
    end
  end
  checks = checks + 1
  return not diverged
end

-- The recorded column is compared with 1e-6 on the two floats: the recorded values
-- are quoted to six decimals, and the pin's own battery pins its margins to the same
-- precision.
local function diffRecorded(label, live, recorded)
  local diverged = false
  for _, field in ipairs(JUDGE_FIELDS) do
    local want = recorded[field]
    local got = live[field]
    local ok
    if type(want) == "number" and type(got) == "number" then
      ok = math.abs(want - got) <= 1e-6
    else
      ok = (want == got)
    end
    if not ok then
      diverged = true
      failed = failed + 1
      io.stderr:write(("FAIL: %s: recorded %s = %s, measured %s\n")
        :format(label, field, shown(want), shown(got)))
    end
  end
  checks = checks + 1
  return not diverged
end

-- ═══════════════════════════════════════════════════════════════════════════════
-- 5. Every case, both sides, verbatim
-- ═══════════════════════════════════════════════════════════════════════════════
-- (a) is `Arbitration.judge` on the pin's bytes in a bare environment;
-- (b) is `Verdict.arbitrate` on the pack's wiring. The state word is the model's
-- (SIDEGRADE) and the token is the surface's (TRADE_OFF); the map between them is
-- the pack's own, so the comparison asks the pack to account for its own token.

for _, input in ipairs(CASES) do
  local label = input.label
  print("")
  print(("-- %s %s"):format(label, string.rep("-", math.max(4, 74 - #label))))
  print(("   %s"):format(input.note))
  print(("   chest   cand { %s }   vs   eq { %s }"):format(pairOf(input.cand), pairOf(input.eq)))
  print(("   state   raid · measured mid (level 34, 2060 mana, +36 Healing)%s")
    :format(input.totals and ", totals flagged secret" or ""))

  local a = judgeRecord(REF.Arbitration, input)
  local b = wiredRecord(PV, PA, input)
  local c = judgeRecord(PINORDER.Arbitration, input)

  printSide("(a) StatForge @ 1992240      ", a, false)
  printSide("(b) MightiePack (vendored)    ", b, true)

  -- The seam's contract: the token is the pack's map of the model's state.
  local mapped = PV.ARBITRATION_STATE_TOKEN[a.state or ""]
  check(b.token == mapped,
    ("%s: (b) token %s is the pack's token for (a) state %s (expected %s)")
      :format(label, q(b.token), q(a.state), q(mapped)))
  -- A refusal is nil on both sides, and the reason a refusal carries is its answer.
  check((a.state == nil) == (b.state == nil),
    ("%s: both sides judge or both refuse (a.state=%s, b.state=%s)")
      :format(label, q(a.state), q(b.state)))
  -- The seam's second return is the model's own sentence. When the model JUDGED,
  -- it is the reason, passed through untouched — both places the seam can rewrite
  -- one (SURVIVAL_SENTENCE in a sidegrade, BUFF_WARNING on totals.buffed) are silent
  -- on these five inputs. When the model REFUSED, A8 (card t_18eb91e6) makes the
  -- refusal itself the answer: the same second slot carries it, the detail is marked
  -- `declined = true`, and the model's stable cause key rides beside it. A refusal
  -- that silently answers nil here is the defect the clause map exists to end.
  if a.state ~= nil then
    check(b.tokenReason == b.reason,
      ("%s: the seam passed the reason through unrewritten (tokenReason=%s, reason=%s)")
        :format(label, q(b.tokenReason), q(b.reason)))
    check(b.declined == nil,
      ("%s: a judged pair is not marked declined (declined=%s)")
        :format(label, q(b.declined)))
  else
    check(b.tokenReason == a.why,
      ("%s: the seam hands the refusal up unchanged (tokenReason=%s, why=%s)")
        :format(label, q(b.tokenReason), q(a.why)))
    check(b.declined == true,
      ("%s: a refused pair is marked declined in the detail (declined=%s)")
        :format(label, q(b.declined)))
    check(b.cause == input.recorded.cause,
      ("%s: the decline carries the pin's cause key %s (got %s)")
        :format(label, q(input.recorded.cause), q(b.cause)))
  end

  diffRecorded(label, a, input.recorded)
  diffJudge(label, a, b)
  diffJudge(label .. " (pack order vs pin order)", a, c)

  -- (b) against the recorded upstream seam: the token and the sentence the pin's own
  -- Verdict.arbitrate returned for this input. For a judged pair the sentence is the
  -- reason; for a refusal it is `why` (the recorded `reason` is nil there, and A8
  -- makes the refusal the second return — see the branch above).
  check(b.token == input.recorded.token,
    ("%s: (b) token %s is the recorded 1992240 token %s")
      :format(label, q(b.token), q(input.recorded.token)))
  check(b.tokenReason == (input.recorded.reason or input.recorded.why),
    ("%s: (b) reason %s is the recorded 1992240 seam sentence %s")
      :format(label, q(b.tokenReason), q(input.recorded.reason or input.recorded.why)))
end

-- ═══════════════════════════════════════════════════════════════════════════════
-- 6. StatOrders — the other half of the pair
-- ═══════════════════════════════════════════════════════════════════════════════
-- The arbitration is handed parsed stats; the ORDER in force is a separate published
-- claim, and Step 3's answer names where it came from. The two sides must publish the
-- same claim, with the same provenance id, and refuse the same lookups.

local function orderSignature(order, source)
  if order == nil then return "nil" end
  local entries = {}
  for i = 1, #order do entries[i] = tostring(order[i]) end
  return (source or "nil") .. " [" .. #order .. "]: " .. table.concat(entries, " > ")
end

local LOOKUPS = {
  { "Raid", "PALADIN", "Holy", "an endgame spec claim" },
  { "Dungeon", "PALADIN", "Holy", "the same claim — dungeon resolves through endgame" },
  { "Leveling", "PALADIN", "Holy", "a leveling claim (per class: the spec is ignored)" },
  { "Raid", "WARRIOR", "Protection", "a tank row the Step 3 model never weights" },
  { "Raid", "PALADIN", "Nonexistent", "an unknown spec — no neighbouring list is invented" },
  { "Battleground", "PALADIN", "Holy", "an unknown context — no fallback" },
}

print("")
print("-- StatOrders (context / class / spec) ------------------------------------")
for _, look in ipairs(LOOKUPS) do
  local context, class, spec, note = look[1], look[2], look[3], look[4]
  local refOrder, refSource = REF.StatOrders.get(context, class, spec)
  local packOrder, packSource = PACKED.StatOrders.get(context, class, spec)
  local aSig = orderSignature(refOrder, refSource)
  local bSig = orderSignature(packOrder, packSource)
  print(("   %-12s %-8s %-12s %s"):format(context, class, tostring(spec), note))
  print(("     (a) %s"):format(aSig))
  print(("     (b) %s"):format(bSig))
  check(aSig == bSig, ("StatOrders %s/%s/%s: (a) and (b) agree (a=%s b=%s)")
    :format(context, class, tostring(spec), aSig, bSig))
end

-- The documented shape: the order is the ONE stored table for that claim, so two
-- lookups that resolve to the same claim are rawequal (a copy would break callers
-- that compare them, and this file is data, not a factory).
local orderA, sourceA = REF.StatOrders.get("Raid", "PALADIN", "Holy")
local orderB, sourceB = REF.StatOrders.get("Dungeon", "PALADIN", "Holy")
check(orderA == orderB and sourceA == sourceB,
  "StatOrders: Raid and Dungeon resolve to the same claim object (published once, cited once)")
check(REF.StatOrders.phaseFor("Leveling") == "leveling"
  and REF.StatOrders.phaseFor("Raid") == "endgame"
  and REF.StatOrders.phaseFor("Battleground") == nil,
  "StatOrders: the context regime map is the published one")

-- ═══════════════════════════════════════════════════════════════════════════════
-- Summary
-- ═══════════════════════════════════════════════════════════════════════════════

print("")
if failed > 0 then
  print(("%d check(s) failed"):format(failed))
  os.exit(1)
end
print(("%d check(s) passed: 4 Step 3 states, both sides identical"):format(checks))
